pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, address user, uint256 collectAmt) public {
        vm.assume(depositAmt > 0 && collectAmt > 0);
        vm.assume(depositAmt <= type(uint128).max);
        vm.assume(collectAmt <= type(uint128).max);
        vm.assume(user != address(0) && user != address(this) && user != address(c));

        // Initialize contract
        c.SetMinSum(0);
        c.SetLogFile(address(0x1));
        c.Initialized();

        // Record initial balance of user
        uint256 initialBal = c.balances(user);

        // Deposit to user
        vm.deal(user, depositAmt);
        vm.prank(user);
        c.Deposit{value: depositAmt}();

        // Collect from user
        vm.prank(user);
        c.Collect(collectAmt);

        uint256 finalBal = c.balances(user);
        uint256 totalDeposited = initialBal + depositAmt;

        // After a deposit and a collect, the balance must not exceed totalDeposited (collected amount is removed)
        // Under normal operation: finalBal = initialBal + depositAmt - collectAmt <= totalDeposited
        // Buggy Deposit subtracts value: initialBal - depositAmt (underflow if initialBal < depositAmt) -> huge balance, violating rule
        assertTrue(finalBal <= totalDeposited, "balance exceeds total deposited");
    }
}

