pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, address depositor, address collector) public {
        // Restrict to safe and admissible domain: non-zero addresses and amounts within bounds
        vm.assume(depositor != address(0) && collector != address(0));
        vm.assume(depositAmt > 0 && depositAmt < type(uint128).max);
        vm.assume(collectAmt > 0 && collectAmt < type(uint128).max);

        // Setup: deploy, initialize, set MinSum
        address log = address(new LogFile());
        c.SetLogFile(log);
        c.SetMinSum(0);
        c.Initialized();

        // Fund depositor and deposit
        vm.deal(depositor, depositAmt);
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // Allow collector to have some balance if different, else use depositor's own
        if (collector != depositor) {
            // Give collector some balance via a second deposit to enable Collect
            vm.deal(collector, depositAmt);
            vm.prank(collector);
            c.Deposit{value: depositAmt}();
        }

        // Set MinSum to allow collect
        c.SetMinSum(0);

        // Collect: try to withdraw from collector
        vm.prank(collector);
        try c.Collect(collectAmt) { } catch { }

        // Sum balances of the two accounts we used
        uint256 sumBalances = c.balances(depositor) + c.balances(collector);

        // Assert sum of balances equals contract's Ether balance
        assertTrue(sumBalances == address(c).balance);
    }
}

